#!/usr/bin/env node
// Flags stock AI phrasing in README.md and docs/**/*.md.
// Fenced code, inline code, and blockquotes are skipped, so quoted examples pass.
// Known findings live in prose-baseline.json; only findings missing from it fail.
// Usage: node scripts/lint-prose.mjs [--write-baseline]

import { readFile, readdir, writeFile } from 'node:fs/promises';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const BASELINE_PATH = join(ROOT, 'prose-baseline.json');
const WRITE_BASELINE = process.argv.includes('--write-baseline');

const RULES = [
  {
    id: 'chatbot-closer',
    pattern: /\b(let me know if (you (have|need)|there(’|')?s)|hope (this|that) helps|feel free to (reach out|ask)|great question|happy (coding|learning))\b/i,
  },
  {
    id: 'filler-opener',
    pattern: /\b(in today(’|')?s (fast-paced|fast-moving|ever-changing|ever-evolving|digital|modern) |it(’|')?s (important|worth) to note|it is (important|worth) to note)/i,
  },
  {
    id: 'stock-vocabulary',
    pattern: /\b(delve[sd]?|delving|testament to|tapestry|seamless(ly)?|game-chang(er|ing)|unlock the (power|potential) of|elevate your|embark on a journey|the future of [\w\s-]{1,40} looks bright)\b/i,
  },
];

async function markdownFiles(dir) {
  const entries = await readdir(dir, { withFileTypes: true });
  const files = [];
  for (const entry of entries) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) files.push(...(await markdownFiles(path)));
    else if (entry.name.endsWith('.md')) files.push(path);
  }
  return files;
}

// Yields prose lines only: skips fenced code, blockquotes, and inline code spans.
function* proseLines(text) {
  let inFence = false;
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i];
    if (/^\s*(```|~~~)/.test(raw)) {
      inFence = !inFence;
      continue;
    }
    if (inFence || /^\s*>/.test(raw)) continue;
    yield { number: i + 1, raw, text: raw.replace(/`[^`]*`/g, '') };
  }
}

async function findings() {
  const files = [join(ROOT, 'README.md'), ...(await markdownFiles(join(ROOT, 'docs')))];
  const results = [];
  for (const file of files) {
    const rel = relative(ROOT, file);
    const text = await readFile(file, 'utf8');
    for (const line of proseLines(text)) {
      for (const rule of RULES) {
        const match = line.text.match(rule.pattern);
        if (match) {
          results.push({
            file: rel,
            line: line.number,
            rule: rule.id,
            match: match[0],
            key: `${rel}\t${rule.id}\t${line.raw.trim()}`,
          });
        }
      }
    }
  }
  return results;
}

async function loadBaseline() {
  try {
    const entries = JSON.parse(await readFile(BASELINE_PATH, 'utf8'));
    return new Set(entries.map((e) => `${e.file}\t${e.rule}\t${e.line}`));
  } catch (err) {
    if (err.code === 'ENOENT') return new Set();
    throw err;
  }
}

const all = await findings();

if (WRITE_BASELINE) {
  const entries = [...new Map(all.map((f) => [f.key, f])).values()].map((f) => ({
    file: f.file,
    rule: f.rule,
    line: f.key.split('\t')[2],
  }));
  entries.sort((a, b) => `${a.file}${a.rule}${a.line}`.localeCompare(`${b.file}${b.rule}${b.line}`));
  await writeFile(BASELINE_PATH, JSON.stringify(entries, null, 2) + '\n');
  console.log(`Wrote ${entries.length} baseline entries to ${relative(ROOT, BASELINE_PATH)}`);
  process.exit(0);
}

const baseline = await loadBaseline();
const fresh = all.filter((f) => !baseline.has(f.key));

if (fresh.length > 0) {
  console.error('Stock AI phrasing found. Rewrite these lines in plain words:\n');
  for (const f of fresh) {
    console.error(`${f.file}:${f.line}  [${f.rule}]  "${f.match}"`);
  }
  console.error(`\n${fresh.length} finding(s).`);
  process.exit(1);
}

console.log(`prose lint passed (${all.length} known finding(s) in baseline).`);

